#Faithfulness Metric
# checks whether the agent's answer actually factually aligns with the contents of your retrieval_context.
# It uses an LLM as a judge to evaluate the relationship between:
#  1. input — the question asked by the user.
#  2. actual_output — the answer generated by your RAG agent.
#  3. retrieval_context - the information your retriever found in the knowledge base 
#     and supplied to the LLM to answer the user's question.
import os
import sys
import pytest

sys.path.insert(
    0,
    os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
)
from deepeval.test_case import LLMTestCase
from deepeval.metrics import FaithfulnessMetric
from app.rag_agent import rag_support_agent_with_context
from app.retriever import build_vector_store

@pytest.fixture(scope="session", autouse=True)
def initialize_vector_store():
    build_vector_store()

@pytest.mark.parametrize("question", [
    "Can I downgrade from Premium to Basic today and immediately pay the Basic price?",
    "My monthly renewal date is the 31st. Will I always be charged on the 31st of every month?",
    "My renewal payment failed. Will you retry charging my card tomorrow?",
    "I cancelled my Premium subscription today. Can I get a refund for the unused days?",
    "I'm the account holder's colleague. Can you tell me their current subscription plan and saved payment details?"
])

def test_faithfulness_agent_response(question):
    response = rag_support_agent_with_context(question)

    test_case = LLMTestCase(
        input = question,
        actual_output = response["answer"],
        retrieval_context= response["retrieval_context"]
    )

    metric = FaithfulnessMetric(
        threshold = 0.8,
        model="gpt-4.1-mini",
        include_reason= True

    )

    metric.measure(test_case)

    print(
        f"Metric score: {metric.score}\n"
        f"Metric reason: {metric.reason}\n"
        f"Agent Answer: {response['answer']}" 
    )

    assert metric.is_successful() , (
        f"Question: {question}\n"
        f"Score: {metric.score}\n"
        f"Reason: {metric.reason}\n"
        f"Answer: {response['answer']}"
    )

